1: using StudentManagement.Core;
2: namespace StudentManagement.Web;
3: public sealed class WebStudentCoordinator(IStudentService service,RequestIdentity identity,SearchContextStore contexts)
4: {
5:     public SearchContextStore.Entry NewContext(string? tab=null)=>contexts.Create(identity.CurrentUser,tab);
6:     public void CheckReturn(string? id) { if(!string.IsNullOrEmpty(id)) contexts.Get(id,identity.CurrentUser); }
7:     public async Task<object> Search(SearchRequest request,string? tab,CancellationToken ct) {
8:         identity.Read(); var criteria=request.Criteria.ToCriteria(request.PageSize,request.SortKey,request.SortDirection);
9:         return await contexts.Use(request,identity.CurrentUser,tab,async entry=> { var result=await service.SearchAsync(criteria,ct); EnsureSearch(result); entry.Applied=SearchContextStore.Copy(criteria);entry.LastResult=result; entry.Revision++; return Present(entry,result); },ct);
10:     }
11:     public async Task<object> Page(PageRequest request,string? tab,CancellationToken ct) {
12:         identity.Read(); return await contexts.Use(request,identity.CurrentUser,tab,async entry=> { if(entry.Applied is null) throw new WebFault(409,"先に検索してください。"); var criteria=SearchContextStore.Copy(entry.Applied); criteria.Page=criteria.PageSize!=request.PageSize||criteria.SortKey!=request.SortKey||criteria.SortDirection!=request.SortDirection?1:request.Page; criteria.PageSize=request.PageSize; criteria.SortKey=request.SortKey;criteria.SortDirection=request.SortDirection; var result=await service.SearchAsync(criteria,ct); EnsureSearch(result); if(!result.LimitExceeded&&criteria.Page>Math.Max(1,(result.Count+criteria.PageSize-1)/criteria.PageSize)) { criteria.Page=Math.Max(1,(result.Count+criteria.PageSize-1)/criteria.PageSize);result=await service.SearchAsync(criteria,ct);EnsureSearch(result); } entry.Applied=SearchContextStore.Copy(criteria);entry.LastResult=result;entry.Revision++;return Present(entry,result); },ct);
13:     }
